package com.yeyamo_mobile.api.messaging_service.infrastructure.persistence;
import java.time.Instant;import java.util.UUID;import org.springframework.data.cassandra.core.cql.PrimaryKeyType;import org.springframework.data.cassandra.core.mapping.*;import com.yeyamo_mobile.api.messaging_service.domain.*;
@Table("conversations_by_user")public class ConversationByUserEntity{@PrimaryKeyColumn(name="user_id",type=PrimaryKeyType.PARTITIONED)private String userId;@PrimaryKeyColumn(name="conversation_id",type=PrimaryKeyType.CLUSTERED)private UUID conversationId;@Column private MemberRole role;@Column private MemberStatus status;@Column private String title;@Column("conversation_type")private ConversationType conversationType;@Column("updated_at")private Instant updatedAt;@Column("last_message_preview")private String lastMessagePreview;@Column("last_message_at")private Instant lastMessageAt;
 public static ConversationByUserEntity from(ConversationEntity c,ConversationMemberEntity m){var x=new ConversationByUserEntity();x.userId=m.getUserId();x.conversationId=c.getId();x.role=m.getRole();x.status=m.getStatus();x.title=c.getTitle();x.conversationType=c.getType();x.updatedAt=c.getUpdatedAt();x.lastMessagePreview=c.getLastMessagePreview();x.lastMessageAt=c.getLastMessageAt();return x;}
 public String getUserId(){return userId;}public UUID getConversationId(){return conversationId;}public MemberRole getRole(){return role;}public MemberStatus getStatus(){return status;}public String getTitle(){return title;}public ConversationType getConversationType(){return conversationType;}public Instant getUpdatedAt(){return updatedAt;}public String getLastMessagePreview(){return lastMessagePreview;}public Instant getLastMessageAt(){return lastMessageAt;}}
